export const TRICK_KEY = "umbral";
export const TRICKS = ["silhouette", "adumbrate", "occultation", "antumbra", "caligo", "sfumato", "tenebrae"] as const;
export const HAPPY = ["skotos", "umbriel", "softfall"] as const;
export type UmbralTrickKind = (typeof TRICKS)[number];
export type UmbralHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type UmbralTrick = {
  kind: UmbralTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type UmbralHappy = {
  kind: UmbralHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR: Record<UmbralHappyKind, number> = {
  skotos: 1.28,
  umbriel: 1.16,
  softfall: 1.22,
};

/** Caligo hold — Hush parks soft murky shade calm as heat-shadow desk life. Not window-play COOL. */
export const CALIGO_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR: Record<UmbralTrickKind, number> = {
  caligo: CALIGO_HOLD + RELEASE_S,
  silhouette: 1.58,
  adumbrate: 1.64,
  occultation: 1.48,
  antumbra: 1.56,
  sfumato: 1.68,
  tenebrae: 1.72,
};

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: UmbralTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "caligo") return 40 + roll * 26;
  if (kind === "silhouette" || kind === "adumbrate" || kind === "occultation" || kind === "antumbra" || kind === "sfumato" || kind === "tenebrae") return 12.8 + roll * 9.4;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

export function pickTrick(rand?: number, musicOn?: boolean, lastKind?: UmbralTrickKind | string | null) {
  if (musicOn) return "caligo" as const;
  const roll = rand == null ? Math.random() : rand;
  const pool = TRICKS.filter((k) => k !== lastKind);
  const list = pool.length ? pool : TRICKS.slice();
  const weights = list.map((k) =>
    k === "caligo" ? 0.72 : k === "silhouette" || k === "sfumato" ? 1.28 : k === "tenebrae" ? 1.18 : 1.08
  );
  let total = 0;
  for (let i = 0; i < weights.length; i++) total += weights[i];
  let r = roll * total;
  for (let i = 0; i < list.length; i++) {
    r -= weights[i];
    if (r <= 0) return list[i];
  }
  return list[list.length - 1] || "silhouette";
}

export function happyCanStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function happyShouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function wantsThankYou(key: string | undefined | null) {
  return key === TRICK_KEY || key === "hush";
}

export function startThankYou(
  key: string | undefined | null,
  lastKind: UmbralHappyKind | string | null | undefined,
  x: number,
  facing: 1 | -1,
  flags?: TrickFlags,
) {
  if (!wantsThankYou(key)) return null;
  if (!happyCanStart(flags || { cmd: "idle" })) return null;
  const pick = pickHappy(lastKind as UmbralHappyKind | null | undefined);
  return { happy: beginHappy(pick, x, facing), kind: pick };
}

export function pickHappy(lastKind?: UmbralHappyKind | null, rand?: number) {
  const pool = HAPPY.filter((k) => k !== lastKind);
  const list = pool.length ? pool : [...HAPPY];
  const roll = rand == null ? Math.random() : rand;
  return list[Math.floor(roll * list.length)] || list[0];
}

export function beginHappy(kind: UmbralHappyKind | string, x: number, facing: 1 | -1): UmbralHappy {
  const name = (HAPPY as readonly string[]).indexOf(kind) >= 0 ? (kind as UmbralHappyKind) : "skotos";
  return {
    kind: name,
    happy: true,
    phase: "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: name === "skotos" ? "talk" : name === "umbriel" ? "play" : "sit",
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

export function skotosPose(t: number) {
  const u = Math.max(0, Math.min(1, t / HAPPY_DUR.skotos));
  if (u < 0.2) {
    const s = u / 0.2;
    return { lift: s * 3.36, rot: s * 14.4, dx: 0, anim: "talk" as TrickAnim };
  }
  if (u < 0.76) {
    const tick = Math.sin(t * 1.72);
    return {
      lift: 3.36 + Math.abs(tick) * 1.68,
      rot: 14.4 + tick * 12,
      dx: tick * 0.14,
      anim: "talk" as TrickAnim,
    };
  }
  const s = (u - 0.76) / 0.24;
  return { lift: 2.4 * (1 - s), rot: 7.2 * (1 - s), dx: 0, anim: "talk" as TrickAnim };
}

export function umbrielPose(t: number) {
  const u = Math.max(0, Math.min(1, t / HAPPY_DUR.umbriel));
  if (u < 0.18) {
    const s = u / 0.18;
    return { lift: s * 4.08, rot: s * -16.8, dx: s * 0.18, anim: "play" as TrickAnim };
  }
  if (u < 0.78) {
    const flash = Math.sin(t * 2.1);
    return {
      lift: 4.08 + Math.abs(flash) * 1.92,
      rot: -16.8 + flash * 14.4,
      dx: flash * 0.22,
      anim: "play" as TrickAnim,
    };
  }
  const s = (u - 0.78) / 0.22;
  return { lift: 2.64 * (1 - s), rot: -7.2 * (1 - s), dx: 0, anim: "sit" as TrickAnim };
}

export function softfallPose(t: number) {
  return {
    lift: 2.64 + Math.abs(Math.sin(t * 0.58)) * 1.32,
    rot: Math.sin(t * 0.9) * 9.6,
    dx: Math.sin(t * 0.7) * 0.12,
    anim: "sit" as TrickAnim,
  };
}

export function stepHappy(happy: UmbralHappy, dt: number, flags: TrickFlags): UmbralHappy {
  if (!happy || happy.phase === "done") return happy;
  if (happyShouldAbort(flags)) {
    return { ...happy, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: UmbralHappy = { ...happy, t: happy.t + Math.max(0, dt) };
  const hold = HAPPY_DUR[next.kind];
  let pose;
  if (next.kind === "skotos") pose = skotosPose(next.t);
  else if (next.kind === "umbriel") pose = umbrielPose(next.t);
  else pose = softfallPose(next.t);
  next.lift = pose.lift;
  next.rot = pose.rot;
  next.anim = pose.anim;
  next.x = next.fromX + (pose.dx || 0) * next.facing;
  if (next.t >= hold) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}

export function sleepHoldFrame(_key?: string | null, _frameCount?: number) {
  return null;
}

export function beginTrick(kind: UmbralTrickKind, x: number, facing: 1 | -1): UmbralTrick {
  const anim: TrickAnim =
    kind === "caligo"
      ? "sit"
      : kind === "silhouette"
        ? "walk"
        : kind === "adumbrate"
          ? "talk"
          : kind === "occultation"
            ? "sleep"
            : kind === "antumbra"
              ? "play"
              : kind === "sfumato"
                ? "sit"
                : kind === "tenebrae"
                  ? "play"
                  : "sit";
  return {
    kind: kind,
    phase: kind === "caligo" ? "hold" : "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}

/** Caligo — long soft murky shade hold. Not window-play COOL. */
export function caligoPose(t: number) {
  return {
    lift: 2.88 + Math.abs(Math.sin(t * 0.42)) * 1.44,
    rot: Math.sin(t * 0.55) * 7.2,
  };
}

export function releasePose(t: number) {
  const u = Math.max(0, Math.min(1, t / RELEASE_S));
  const s = Math.sin(u * Math.PI * 0.5);
  return { lift: 2.88 * (1 - s), rot: 4.8 * (1 - s) };
}

export function silhouettePose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.silhouette));
  if (u < 0.16) {
    const s = smoothstep(u / 0.16);
    return { x: fromX, lift: s * 3.84, rot: s * -9.6 * facing, anim: "sit" as TrickAnim };
  }
  if (u < 0.62) {
    const s = (u - 0.16) / 0.46;
    const bob = Math.sin(s * Math.PI * 3.4);
    return {
      x: fromX + facing * (s * 0.96 + bob * 0.18),
      lift: 3.84 - s * 0.96 + Math.abs(bob) * 0.72,
      rot: facing * (-9.6 + bob * 14.4),
      anim: "walk" as TrickAnim,
    };
  }
  if (u < 0.84) {
    const settle = smoothstep((u - 0.62) / 0.22);
    return {
      x: fromX + facing * 0.96 * (1 - settle * 0.48),
      lift: 2.88 * (1 - settle * 1.02),
      rot: facing * (-4.8 + settle * 9.6),
      anim: "sit" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.84) / 0.16);
  return {
    x: fromX + facing * 0.58 * (1 - s),
    lift: 0.96 * (1 - s),
    rot: facing * (2.4 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function adumbratePose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.adumbrate));
  if (u < 0.14) {
    const s = smoothstep(u / 0.14);
    return { x: fromX, lift: s * 3.12, rot: s * -12 * facing, anim: "talk" as TrickAnim };
  }
  if (u < 0.72) {
    const s = (u - 0.14) / 0.58;
    const open = Math.sin(s * Math.PI * 3.6);
    return {
      x: fromX + facing * (s * 0.54 + open * 0.14),
      lift: 3.12 + Math.abs(open) * 1.92,
      rot: facing * (-12 + open * 19.2),
      anim: "talk" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.72) / 0.28);
  return {
    x: fromX + facing * 0.54 * (1 - s),
    lift: 2.16 * (1 - s),
    rot: facing * (-4.8 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function occultationPose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.occultation));
  if (u < 0.16) {
    const s = smoothstep(u / 0.16);
    return { x: fromX, lift: s * 2.88, rot: s * 16.8 * facing, anim: "sit" as TrickAnim };
  }
  if (u < 0.55) {
    const s = (u - 0.16) / 0.39;
    const press = Math.sin(s * Math.PI * 2.8);
    return {
      x: fromX + facing * (s * 0.42),
      lift: 2.88 + Math.abs(press) * 1.68,
      rot: facing * (16.8 - press * 12),
      anim: "sleep" as TrickAnim,
    };
  }
  if (u < 0.82) {
    const settle = smoothstep((u - 0.55) / 0.27);
    return {
      x: fromX + facing * 0.42,
      lift: 3.84 - settle * 1.44,
      rot: facing * (7.2 + settle * 4.8),
      anim: "sleep" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.82) / 0.18);
  return {
    x: fromX + facing * 0.42 * (1 - s),
    lift: 2.4 * (1 - s),
    rot: facing * (4.8 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function antumbraPose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.antumbra));
  if (u < 0.14) {
    const s = smoothstep(u / 0.14);
    return { x: fromX, lift: s * 3.12, rot: s * 12 * facing, anim: "talk" as TrickAnim };
  }
  if (u < 0.4) {
    const s = (u - 0.14) / 0.26;
    const cup = smoothstep(s);
    return {
      x: fromX + facing * cup * 0.66,
      lift: 3.12 * (1 - cup * 0.84),
      rot: facing * (12 - cup * 7.2),
      anim: "play" as TrickAnim,
    };
  }
  if (u < 0.78) {
    const s = (u - 0.4) / 0.38;
    const hold = Math.sin(s * Math.PI * 2.6);
    return {
      x: fromX + facing * 0.66,
      lift: 0.96 + Math.abs(hold) * 0.72 + 2.4,
      rot: facing * (-4.8 + hold * 12),
      anim: "play" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX + facing * 0.66 * (1 - s),
    lift: 0.72 * (1 - s) + 1.68 * (1 - s),
    rot: facing * (2.4 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function sfumatoPose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.sfumato));
  if (u < 0.16) {
    const s = smoothstep(u / 0.16);
    return { x: fromX, lift: s * 2.16, rot: s * -9.6 * facing, anim: "sit" as TrickAnim };
  }
  if (u < 0.55) {
    const s = (u - 0.16) / 0.39;
    const rock = Math.sin(s * Math.PI * 4.2);
    return {
      x: fromX + facing * (s * 0.72 + rock * 0.24),
      lift: 2.16 + Math.abs(rock) * 1.92,
      rot: facing * (-9.6 + rock * 16.8),
      anim: "sit" as TrickAnim,
    };
  }
  if (u < 0.78) {
    const s = (u - 0.55) / 0.23;
    const spin = Math.sin(s * Math.PI * 3.4);
    return {
      x: fromX + facing * 0.72,
      lift: 3.36 + Math.abs(spin) * 0.96,
      rot: facing * (4.8 + spin * 12),
      anim: "sit" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX + facing * 0.72 * (1 - s),
    lift: 1.92 * (1 - s),
    rot: facing * (2.4 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function tenebraePose(t: number, fromX: number, facing: 1 | -1) {
  const u = Math.max(0, Math.min(1, t / DUR.tenebrae));
  if (u < 0.14) {
    const s = smoothstep(u / 0.14);
    return { x: fromX, lift: s * 3.12, rot: s * 12 * facing, anim: "talk" as TrickAnim };
  }
  if (u < 0.4) {
    const s = (u - 0.14) / 0.26;
    const sip = smoothstep(s);
    return {
      x: fromX + facing * sip * 0.6,
      lift: 3.12 + sip * 2.88,
      rot: facing * (12 + sip * 9.6),
      anim: "talk" as TrickAnim,
    };
  }
  if (u < 0.78) {
    const s = (u - 0.4) / 0.38;
    const drink = Math.sin(s * Math.PI * 3.2);
    return {
      x: fromX + facing * (0.6 + drink * 0.36),
      lift: 5.76 + Math.abs(drink) * 0.96,
      rot: facing * (7.2 + drink * 16.8),
      anim: "play" as TrickAnim,
    };
  }
  const s = smoothstep((u - 0.78) / 0.22);
  return {
    x: fromX + facing * 0.6 * (1 - s),
    lift: 3.12 * (1 - s),
    rot: facing * (7.2 * (1 - s)),
    anim: "idle" as TrickAnim,
  };
}

export function stepTrick(trick: UmbralTrick, dt: number, flags: TrickFlags): UmbralTrick {
  if (!trick || trick.phase === "done") return trick;
  if (
    shouldAbort(flags) &&
    trick.kind !== "silhouette" &&
    trick.kind !== "adumbrate" &&
    trick.kind !== "occultation" &&
    trick.kind !== "antumbra" &&
    trick.kind !== "sfumato" &&
    trick.kind !== "tenebrae"
  ) {
    return { ...trick, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: UmbralTrick = { ...trick, t: trick.t + Math.max(0, dt) };
  if (next.kind === "caligo") {
    if (next.t < CALIGO_HOLD) {
      const pose = caligoPose(next.t);
      next.phase = "hold";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    if (next.t < CALIGO_HOLD + RELEASE_S) {
      const pose = releasePose(next.t - CALIGO_HOLD);
      next.phase = "release";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  }
  const hold = DUR[next.kind];
  const u = next.t / hold;
  const fromX = trick.fromX != null ? trick.fromX : trick.x;
  let pose;
  if (next.kind === "silhouette") pose = silhouettePose(next.t, fromX, trick.facing);
  else if (next.kind === "adumbrate") pose = adumbratePose(next.t, fromX, trick.facing);
  else if (next.kind === "occultation") pose = occultationPose(next.t, fromX, trick.facing);
  else if (next.kind === "antumbra") pose = antumbraPose(next.t, fromX, trick.facing);
  else if (next.kind === "sfumato") pose = sfumatoPose(next.t, fromX, trick.facing);
  else pose = tenebraePose(next.t, fromX, trick.facing);
  next.x = pose.x;
  next.lift = pose.lift;
  next.rot = pose.rot;
  next.anim = pose.anim;
  if (u >= 1) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}
